from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn
from docx.oxml import OxmlElement
import re

def new_doc():
    d = Document()
    for s in d.sections:
        s.left_margin = s.right_margin = Inches(1)
        s.top_margin = s.bottom_margin = Inches(1)
    st = d.styles["Normal"]
    st.font.name = "Times New Roman"
    st.font.size = Pt(12)
    st.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    st.paragraph_format.space_after = Pt(8)
    st.paragraph_format.line_spacing = 1.08
    return d

def add_runs(p, text, size=None, italic_all=False):
    # **bold**, *italic*, __underline__
    tokens = re.split(r"(\*\*.+?\*\*|__.+?__|\*.+?\*)", text)
    for t in tokens:
        if not t:
            continue
        if t.startswith("**") and t.endswith("**"):
            r = p.add_run(t[2:-2]); r.bold = True
        elif t.startswith("__") and t.endswith("__"):
            r = p.add_run(t[2:-2]); r.underline = True
        elif t.startswith("*") and t.endswith("*") and len(t) > 2:
            r = p.add_run(t[1:-1]); r.italic = True
        else:
            r = p.add_run(t)
        if italic_all:
            r.italic = True
        if size:
            r.font.size = Pt(size)
    return p

def para(d, text, align=None, size=None, indent=None, first=None, after=None, before=None, keep=False, italic=False):
    p = d.add_paragraph()
    add_runs(p, text, size=size, italic_all=italic)
    pf = p.paragraph_format
    if align == "center": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    elif align == "right": p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    elif align == "justify": p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    if indent is not None: pf.left_indent = Inches(indent)
    if first is not None: pf.first_line_indent = Inches(first)
    if after is not None: pf.space_after = Pt(after)
    if before is not None: pf.space_before = Pt(before)
    if keep: pf.keep_with_next = True
    return p

def heading(d, text, size=12, align=None, underline=True, before=10):
    p = d.add_paragraph()
    r = p.add_run(text); r.bold = True; r.underline = underline; r.font.size = Pt(size)
    p.paragraph_format.keep_with_next = True
    p.paragraph_format.space_before = Pt(before)
    if align == "center": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    return p

def shade(cell, hexcolor):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement("w:shd")
    shd.set(qn("w:val"), "clear"); shd.set(qn("w:color"), "auto"); shd.set(qn("w:fill"), hexcolor)
    tcPr.append(shd)

def table(d, header, rows, widths, size=9.5):
    t = d.add_table(rows=1, cols=len(header))
    t.style = "Table Grid"
    t.autofit = False
    for i, h in enumerate(header):
        c = t.rows[0].cells[i]
        c.text = ""
        add_runs(c.paragraphs[0], "**" + h + "**", size=size)
        shade(c, "D9E2F3")
    for row in rows:
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""
            parts = v.split("\n")
            add_runs(cells[i].paragraphs[0], parts[0], size=size)
            for extra in parts[1:]:
                add_runs(cells[i].add_paragraph(), extra, size=size)
    for row in t.rows:
        for i, w in enumerate(widths):
            row.cells[i].width = Inches(w)
        trPr = row._tr.get_or_add_trPr()
    # repeat header
    trPr = t.rows[0]._tr.get_or_add_trPr()
    th = OxmlElement("w:tblHeader"); th.set(qn("w:val"), "true"); trPr.append(th)
    for c in t.rows[0].cells: pass
    d.add_paragraph().paragraph_format.space_after = Pt(2)
    return t

def page_number_footer(d, prefix=""):
    for s in d.sections:
        p = s.footer.paragraphs[0]
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        if prefix:
            r = p.add_run(prefix); r.font.size = Pt(8)
        r = p.add_run()
        for kind, txt in (("begin", None), (None, "PAGE"), ("end", None)):
            if kind:
                fc = OxmlElement("w:fldChar"); fc.set(qn("w:fldCharType"), kind); r._r.append(fc)
            else:
                it = OxmlElement("w:instrText"); it.set(qn("xml:space"), "preserve"); it.text = txt; r._r.append(it)
        r.font.size = Pt(9)

def header_text(d, text):
    for s in d.sections:
        p = s.header.paragraphs[0]
        p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
        r = p.add_run(text); r.font.size = Pt(8); r.bold = True
